INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-1000-words-a1-02-01', 'lesson-1000-words-a1-02', 1, 'word', 'red', 'vermelho', '/rɛd/', 'Em inglês o adjetivo vem antes do substantivo: "a red car", não "a car red".', '[]'::jsonb, '[{"surface":"red","pos":"adjective","ipa":"/rɛd/","gloss":"vermelho"}]'::jsonb, 'She has a red car.', 'Ela tem um carro vermelho.'),
  ('unit-1000-words-a1-02-02', 'lesson-1000-words-a1-02', 2, 'word', 'blue', 'azul', '/bluː/', NULL, '[]'::jsonb, '[{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"}]'::jsonb, 'The sky is blue today.', 'O céu está azul hoje.'),
  ('unit-1000-words-a1-02-03', 'lesson-1000-words-a1-02', 3, 'word', 'green', 'verde', '/ɡriːn/', NULL, '[]'::jsonb, '[{"surface":"green","pos":"adjective","ipa":"/ɡriːn/","gloss":"verde"}]'::jsonb, 'I like green tea.', 'Eu gosto de chá verde.'),
  ('unit-1000-words-a1-02-04', 'lesson-1000-words-a1-02', 4, 'word', 'yellow', 'amarelo', '/ˈjɛloʊ/', NULL, '[]'::jsonb, '[{"surface":"yellow","pos":"adjective","ipa":"/ˈjɛloʊ/","gloss":"amarelo"}]'::jsonb, 'The taxi is yellow.', 'O táxi é amarelo.'),
  ('unit-1000-words-a1-02-05', 'lesson-1000-words-a1-02', 5, 'word', 'black', 'preto', '/blæk/', '"Black coffee" = café sem leite.', '[]'::jsonb, '[{"surface":"black","pos":"adjective","ipa":"/blæk/","gloss":"preto"}]'::jsonb, 'I want a black coffee.', 'Quero um café preto (sem leite).'),
  ('unit-1000-words-a1-02-06', 'lesson-1000-words-a1-02', 6, 'word', 'white', 'branco', '/waɪt/', 'O "h" não é pronunciado: /waɪt/.', '[]'::jsonb, '[{"surface":"white","pos":"adjective","ipa":"/waɪt/","gloss":"branco"}]'::jsonb, 'Her dress is white.', 'O vestido dela é branco.'),
  ('unit-1000-words-a1-02-07', 'lesson-1000-words-a1-02', 7, 'word', 'orange', 'laranja', '/ˈɔːrɪndʒ/', 'Serve para a cor e para a fruta; como começa com som de vogal, usa "an": "an orange".', '[]'::jsonb, '[{"surface":"orange","pos":"adjective","ipa":"/ˈɔːrɪndʒ/","gloss":"laranja"}]'::jsonb, 'He wore an orange shirt.', 'Ele usou uma camisa laranja.'),
  ('unit-1000-words-a1-02-08', 'lesson-1000-words-a1-02', 8, 'word', 'purple', 'roxo', '/ˈpɜːrpəl/', NULL, '[]'::jsonb, '[{"surface":"purple","pos":"adjective","ipa":"/ˈpɜːrpəl/","gloss":"roxo"}]'::jsonb, 'Purple is my favorite color.', 'Roxo é minha cor favorita.'),
  ('unit-1000-words-a1-02-09', 'lesson-1000-words-a1-02', 9, 'word', 'pink', 'rosa', '/pɪŋk/', 'A flor rosa é "rose"; a cor é "pink".', '[]'::jsonb, '[{"surface":"pink","pos":"adjective","ipa":"/pɪŋk/","gloss":"rosa"}]'::jsonb, 'She painted her room pink.', 'Ela pintou o quarto de rosa.'),
  ('unit-1000-words-a1-02-10', 'lesson-1000-words-a1-02', 10, 'word', 'brown', 'marrom', '/braʊn/', 'Para olhos e cabelo, "brown" = castanho.', '[]'::jsonb, '[{"surface":"brown","pos":"adjective","ipa":"/braʊn/","gloss":"marrom"}]'::jsonb, 'He has brown eyes.', 'Ele tem olhos castanhos.'),
  ('unit-1000-words-a1-02-11', 'lesson-1000-words-a1-02', 11, 'word', 'gray', 'cinza', '/ɡreɪ/', 'EUA: "gray"; Reino Unido: "grey".', '[]'::jsonb, '[{"surface":"gray","pos":"adjective","ipa":"/ɡreɪ/","gloss":"cinza"}]'::jsonb, 'The weather is gray and cold.', 'O tempo está cinzento e frio.'),
  ('unit-1000-words-a1-02-12', 'lesson-1000-words-a1-02', 12, 'word', 'gold', 'dourado', '/ɡoʊld/', NULL, '[]'::jsonb, '[{"surface":"gold","pos":"adjective","ipa":"/ɡoʊld/","gloss":"dourado; ouro"}]'::jsonb, 'She wears a gold ring.', 'Ela usa um anel de ouro.'),
  ('unit-1000-words-a1-02-13', 'lesson-1000-words-a1-02', 13, 'word', 'silver', 'prateado', '/ˈsɪlvər/', NULL, '[]'::jsonb, '[{"surface":"silver","pos":"adjective","ipa":"/ˈsɪlvər/","gloss":"prateado; prata"}]'::jsonb, 'I have a silver phone.', 'Eu tenho um celular prateado.'),
  ('unit-1000-words-a1-02-14', 'lesson-1000-words-a1-02', 14, 'word', 'beige', 'bege', '/beɪʒ/', NULL, '[]'::jsonb, '[{"surface":"beige","pos":"adjective","ipa":"/beɪʒ/","gloss":"bege"}]'::jsonb, 'The walls are beige.', 'As paredes são bege.'),
  ('unit-1000-words-a1-02-15', 'lesson-1000-words-a1-02', 15, 'word', 'dark', 'escuro', '/dɑːrk/', '"Dark" vem antes da cor: "dark green" = verde-escuro.', '[]'::jsonb, '[{"surface":"dark","pos":"adjective","ipa":"/dɑːrk/","gloss":"escuro"}]'::jsonb, 'I prefer dark blue.', 'Eu prefiro azul-escuro.'),
  ('unit-1000-words-a1-02-16', 'lesson-1000-words-a1-02', 16, 'word', 'light', 'claro', '/laɪt/', '"Light" + cor = tom claro: "light blue" = azul-claro.', '[]'::jsonb, '[{"surface":"light","pos":"adjective","ipa":"/laɪt/","gloss":"claro"}]'::jsonb, 'She bought a light pink bag.', 'Ela comprou uma bolsa rosa-claro.'),
  ('unit-1000-words-a1-02-17', 'lesson-1000-words-a1-02', 17, 'word', 'bright', 'vivo, brilhante', '/braɪt/', NULL, '[]'::jsonb, '[{"surface":"bright","pos":"adjective","ipa":"/braɪt/","gloss":"vivo, brilhante"}]'::jsonb, 'The room has bright colors.', 'O quarto tem cores vivas.'),
  ('unit-1000-words-a1-02-18', 'lesson-1000-words-a1-02', 18, 'word', 'color', 'cor', '/ˈkʌlər/', 'Pergunta pela cor: "What color is…?". Reino Unido: "colour".', '[]'::jsonb, '[{"surface":"color","pos":"noun","ipa":"/ˈkʌlər/","gloss":"cor"}]'::jsonb, 'What color is your car?', 'De que cor é o seu carro?'),
  ('unit-1000-words-a1-02-19', 'lesson-1000-words-a1-02', 19, 'word', 'colorful', 'colorido', '/ˈkʌlərfəl/', NULL, '[]'::jsonb, '[{"surface":"colorful","pos":"adjective","ipa":"/ˈkʌlərfəl/","gloss":"colorido"}]'::jsonb, 'The market is very colorful.', 'O mercado é muito colorido.'),
  ('unit-1000-words-a1-02-20', 'lesson-1000-words-a1-02', 20, 'word', 'rainbow', 'arco-íris', '/ˈreɪnboʊ/', NULL, '[]'::jsonb, '[{"surface":"rainbow","pos":"noun","ipa":"/ˈreɪnboʊ/","gloss":"arco-íris"}]'::jsonb, 'Look, a rainbow!', 'Olha, um arco-íris!')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-1000-words-a1-03-01', 'lesson-1000-words-a1-03', 1, 'word', 'one', 'um', '/wʌn/', 'Pronúncia /wʌn/, igual a "won".', '[]'::jsonb, '[{"surface":"one","pos":"numeral","ipa":"/wʌn/","gloss":"um"}]'::jsonb, 'I have one brother.', 'Eu tenho um irmão.'),
  ('unit-1000-words-a1-03-02', 'lesson-1000-words-a1-03', 2, 'word', 'two', 'dois', '/tuː/', 'Mesmo som de "to" e "too".', '[]'::jsonb, '[{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"}]'::jsonb, 'We have two kids.', 'Nós temos dois filhos.'),
  ('unit-1000-words-a1-03-03', 'lesson-1000-words-a1-03', 3, 'word', 'three', 'três', '/θriː/', 'O "th" é soprado, com a língua entre os dentes.', '[]'::jsonb, '[{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"}]'::jsonb, 'The class starts at three.', 'A aula começa às três.'),
  ('unit-1000-words-a1-03-04', 'lesson-1000-words-a1-03', 4, 'word', 'four', 'quatro', '/fɔːr/', NULL, '[]'::jsonb, '[{"surface":"four","pos":"numeral","ipa":"/fɔːr/","gloss":"quatro"}]'::jsonb, 'There are four people here.', 'Tem quatro pessoas aqui.'),
  ('unit-1000-words-a1-03-05', 'lesson-1000-words-a1-03', 5, 'word', 'five', 'cinco', '/faɪv/', NULL, '[]'::jsonb, '[{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"}]'::jsonb, 'Give me five minutes.', 'Me dá cinco minutos.'),
  ('unit-1000-words-a1-03-06', 'lesson-1000-words-a1-03', 6, 'word', 'six', 'seis', '/sɪks/', NULL, '[]'::jsonb, '[{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"}]'::jsonb, 'I wake up at six.', 'Eu acordo às seis.'),
  ('unit-1000-words-a1-03-07', 'lesson-1000-words-a1-03', 7, 'word', 'seven', 'sete', '/ˈsɛvən/', NULL, '[]'::jsonb, '[{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, 'The store opens at seven.', 'A loja abre às sete.'),
  ('unit-1000-words-a1-03-08', 'lesson-1000-words-a1-03', 8, 'word', 'eight', 'oito', '/eɪt/', 'Pronúncia /eɪt/: o "gh" é mudo.', '[]'::jsonb, '[{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"}]'::jsonb, 'She is eight years old.', 'Ela tem oito anos.'),
  ('unit-1000-words-a1-03-09', 'lesson-1000-words-a1-03', 9, 'word', 'nine', 'nove', '/naɪn/', NULL, '[]'::jsonb, '[{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"}]'::jsonb, 'We have nine rooms.', 'Temos nove quartos.'),
  ('unit-1000-words-a1-03-10', 'lesson-1000-words-a1-03', 10, 'word', 'ten', 'dez', '/tɛn/', NULL, '[]'::jsonb, '[{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"}]'::jsonb, 'It costs ten dollars.', 'Custa dez dólares.'),
  ('unit-1000-words-a1-03-11', 'lesson-1000-words-a1-03', 11, 'word', 'eleven', 'onze', '/ɪˈlɛvən/', NULL, '[]'::jsonb, '[{"surface":"eleven","pos":"numeral","ipa":"/ɪˈlɛvən/","gloss":"onze"}]'::jsonb, 'The bus leaves at eleven.', 'O ônibus sai às onze.'),
  ('unit-1000-words-a1-03-12', 'lesson-1000-words-a1-03', 12, 'word', 'twelve', 'doze', '/twɛlv/', NULL, '[]'::jsonb, '[{"surface":"twelve","pos":"numeral","ipa":"/twɛlv/","gloss":"doze"}]'::jsonb, 'A dozen is twelve.', 'Uma dúzia são doze.'),
  ('unit-1000-words-a1-03-13', 'lesson-1000-words-a1-03', 13, 'word', 'thirteen', 'treze', '/ˌθɜːrˈtiːn/', 'De 13 a 19 a força está no fim: thir-TEEN. Em "thirty" (30) está no começo: THIR-ty.', '[]'::jsonb, '[{"surface":"thirteen","pos":"numeral","ipa":"/ˌθɜːrˈtiːn/","gloss":"treze"}]'::jsonb, 'He is thirteen.', 'Ele tem treze anos.'),
  ('unit-1000-words-a1-03-14', 'lesson-1000-words-a1-03', 14, 'word', 'fourteen', 'catorze', '/ˌfɔːrˈtiːn/', NULL, '[]'::jsonb, '[{"surface":"fourteen","pos":"numeral","ipa":"/ˌfɔːrˈtiːn/","gloss":"catorze"}]'::jsonb, 'I read fourteen pages.', 'Eu li catorze páginas.'),
  ('unit-1000-words-a1-03-15', 'lesson-1000-words-a1-03', 15, 'word', 'fifteen', 'quinze', '/ˌfɪfˈtiːn/', 'É "fif-", não "five-": fifteen.', '[]'::jsonb, '[{"surface":"fifteen","pos":"numeral","ipa":"/ˌfɪfˈtiːn/","gloss":"quinze"}]'::jsonb, 'Wait fifteen minutes.', 'Espere quinze minutos.'),
  ('unit-1000-words-a1-03-16', 'lesson-1000-words-a1-03', 16, 'word', 'sixteen', 'dezesseis', '/ˌsɪksˈtiːn/', NULL, '[]'::jsonb, '[{"surface":"sixteen","pos":"numeral","ipa":"/ˌsɪksˈtiːn/","gloss":"dezesseis"}]'::jsonb, 'She turned sixteen.', 'Ela fez dezesseis anos.'),
  ('unit-1000-words-a1-03-17', 'lesson-1000-words-a1-03', 17, 'word', 'seventeen', 'dezessete', '/ˌsɛvənˈtiːn/', NULL, '[]'::jsonb, '[{"surface":"seventeen","pos":"numeral","ipa":"/ˌsɛvənˈtiːn/","gloss":"dezessete"}]'::jsonb, 'Room seventeen, please.', 'Quarto dezessete, por favor.'),
  ('unit-1000-words-a1-03-18', 'lesson-1000-words-a1-03', 18, 'word', 'eighteen', 'dezoito', '/ˌeɪˈtiːn/', 'Só um "t": eighteen.', '[]'::jsonb, '[{"surface":"eighteen","pos":"numeral","ipa":"/ˌeɪˈtiːn/","gloss":"dezoito"}]'::jsonb, 'You must be eighteen.', 'Você precisa ter dezoito anos.'),
  ('unit-1000-words-a1-03-19', 'lesson-1000-words-a1-03', 19, 'word', 'nineteen', 'dezenove', '/ˌnaɪnˈtiːn/', NULL, '[]'::jsonb, '[{"surface":"nineteen","pos":"numeral","ipa":"/ˌnaɪnˈtiːn/","gloss":"dezenove"}]'::jsonb, 'The flight is at nineteen hundred.', 'O voo é às dezenove horas.'),
  ('unit-1000-words-a1-03-20', 'lesson-1000-words-a1-03', 20, 'word', 'twenty', 'vinte', '/ˈtwɛnti/', 'Na fala rápida americana soa "twenny".', '[]'::jsonb, '[{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"}]'::jsonb, 'I have twenty dollars.', 'Eu tenho vinte dólares.')
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-1000-words-a1-04-01', 'lesson-1000-words-a1-04', 1, 'word', 'keys', 'chaves', '/kiːz/', NULL, '[]'::jsonb, '[{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, 'I can''t find my keys.', 'Não consigo achar minhas chaves.'),
  ('unit-1000-words-a1-04-02', 'lesson-1000-words-a1-04', 2, 'word', 'wallet', 'carteira', '/ˈwɑːlɪt/', '"Wallet" = carteira de dinheiro; carteira de motorista é "driver''s license".', '[]'::jsonb, '[{"surface":"wallet","pos":"noun","ipa":"/ˈwɑːlɪt/","gloss":"carteira"}]'::jsonb, 'My wallet is in my bag.', 'Minha carteira está na bolsa.'),
  ('unit-1000-words-a1-04-03', 'lesson-1000-words-a1-04', 3, 'word', 'passport', 'passaporte', '/ˈpæspɔːrt/', NULL, '[]'::jsonb, '[{"surface":"passport","pos":"noun","ipa":"/ˈpæspɔːrt/","gloss":"passaporte"}]'::jsonb, 'Don''t forget your passport.', 'Não esqueça o passaporte.'),
  ('unit-1000-words-a1-04-04', 'lesson-1000-words-a1-04', 4, 'word', 'phone', 'celular, telefone', '/foʊn/', '"My phone is dead" = a bateria acabou.', '[]'::jsonb, '[{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, 'My phone is dead.', 'Meu celular descarregou.'),
  ('unit-1000-words-a1-04-05', 'lesson-1000-words-a1-04', 5, 'word', 'charger', 'carregador', '/ˈtʃɑːrdʒər/', NULL, '[]'::jsonb, '[{"surface":"charger","pos":"noun","ipa":"/ˈtʃɑːrdʒər/","gloss":"carregador"}]'::jsonb, 'Can I borrow your charger?', 'Posso pegar seu carregador emprestado?'),
  ('unit-1000-words-a1-04-06', 'lesson-1000-words-a1-04', 6, 'word', 'umbrella', 'guarda-chuva', '/ʌmˈbrɛlə/', NULL, '[]'::jsonb, '[{"surface":"umbrella","pos":"noun","ipa":"/ʌmˈbrɛlə/","gloss":"guarda-chuva"}]'::jsonb, 'Take an umbrella, it might rain.', 'Leve um guarda-chuva, pode chover.'),
  ('unit-1000-words-a1-04-07', 'lesson-1000-words-a1-04', 7, 'word', 'glasses', 'óculos', '/ˈɡlæsɪz/', 'Sempre no plural: "my glasses are…". "Sunglasses" = óculos de sol.', '[]'::jsonb, '[{"surface":"glasses","pos":"noun","ipa":"/ˈɡlæsɪz/","gloss":"óculos"}]'::jsonb, 'I need my glasses to read.', 'Preciso dos óculos para ler.'),
  ('unit-1000-words-a1-04-08', 'lesson-1000-words-a1-04', 8, 'word', 'bag', 'bolsa, sacola, mala', '/bæɡ/', NULL, '[]'::jsonb, '[{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"bolsa, sacola, mala"}]'::jsonb, 'Do you need a bag?', 'Você precisa de sacola?'),
  ('unit-1000-words-a1-04-09', 'lesson-1000-words-a1-04', 9, 'word', 'backpack', 'mochila', '/ˈbækpæk/', NULL, '[]'::jsonb, '[{"surface":"backpack","pos":"noun","ipa":"/ˈbækpæk/","gloss":"mochila"}]'::jsonb, 'My laptop is in my backpack.', 'Meu notebook está na mochila.'),
  ('unit-1000-words-a1-04-10', 'lesson-1000-words-a1-04', 10, 'word', 'watch', 'relógio de pulso', '/wɑːtʃ/', '"Watch" = relógio de pulso; relógio de parede é "clock".', '[]'::jsonb, '[{"surface":"watch","pos":"noun","ipa":"/wɑːtʃ/","gloss":"relógio de pulso"}]'::jsonb, 'My watch is slow.', 'Meu relógio está atrasado.'),
  ('unit-1000-words-a1-04-11', 'lesson-1000-words-a1-04', 11, 'word', 'money', 'dinheiro', '/ˈmʌni/', 'Incontável: "much money", nunca "moneys".', '[]'::jsonb, '[{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"}]'::jsonb, 'I don''t have any money.', 'Não tenho dinheiro nenhum.'),
  ('unit-1000-words-a1-04-12', 'lesson-1000-words-a1-04', 12, 'word', 'toothbrush', 'escova de dentes', '/ˈtuːθbrʌʃ/', NULL, '[]'::jsonb, '[{"surface":"toothbrush","pos":"noun","ipa":"/ˈtuːθbrʌʃ/","gloss":"escova de dentes"}]'::jsonb, 'I forgot my toothbrush.', 'Esqueci minha escova de dentes.'),
  ('unit-1000-words-a1-04-13', 'lesson-1000-words-a1-04', 13, 'word', 'towel', 'toalha', '/ˈtaʊəl/', NULL, '[]'::jsonb, '[{"surface":"towel","pos":"noun","ipa":"/ˈtaʊəl/","gloss":"toalha"}]'::jsonb, 'Can I have a clean towel?', 'Pode me dar uma toalha limpa?'),
  ('unit-1000-words-a1-04-14', 'lesson-1000-words-a1-04', 14, 'word', 'medicine', 'remédio', '/ˈmɛdɪsən/', NULL, '[]'::jsonb, '[{"surface":"medicine","pos":"noun","ipa":"/ˈmɛdɪsən/","gloss":"remédio"}]'::jsonb, 'Take this medicine twice a day.', 'Tome este remédio duas vezes ao dia.'),
  ('unit-1000-words-a1-04-15', 'lesson-1000-words-a1-04', 15, 'word', 'ticket', 'passagem, ingresso', '/ˈtɪkɪt/', NULL, '[]'::jsonb, '[{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, ingresso"}]'::jsonb, 'I bought the tickets online.', 'Comprei as passagens pela internet.'),
  ('unit-1000-words-a1-04-16', 'lesson-1000-words-a1-04', 16, 'word', 'notebook', 'caderno', '/ˈnoʊtbʊk/', 'Falso cognato: "notebook" é caderno; o computador é "laptop".', '[]'::jsonb, '[{"surface":"notebook","pos":"noun","ipa":"/ˈnoʊtbʊk/","gloss":"caderno"}]'::jsonb, 'Write it in your notebook.', 'Escreva no seu caderno.'),
  ('unit-1000-words-a1-04-17', 'lesson-1000-words-a1-04', 17, 'word', 'headphones', 'fones de ouvido', '/ˈhɛdfoʊnz/', NULL, '[]'::jsonb, '[{"surface":"headphones","pos":"noun","ipa":"/ˈhɛdfoʊnz/","gloss":"fones de ouvido"}]'::jsonb, 'I always travel with headphones.', 'Eu sempre viajo com fones de ouvido.'),
  ('unit-1000-words-a1-04-18', 'lesson-1000-words-a1-04', 18, 'word', 'bottle', 'garrafa', '/ˈbɑːtəl/', NULL, '[]'::jsonb, '[{"surface":"bottle","pos":"noun","ipa":"/ˈbɑːtəl/","gloss":"garrafa"}]'::jsonb, 'A bottle of water, please.', 'Uma garrafa de água, por favor.'),
  ('unit-1000-words-a1-04-19', 'lesson-1000-words-a1-04', 19, 'word', 'tissues', 'lenços de papel', '/ˈtɪʃuːz/', NULL, '[]'::jsonb, '[{"surface":"tissues","pos":"noun","ipa":"/ˈtɪʃuːz/","gloss":"lenços de papel"}]'::jsonb, 'Do you have any tissues?', 'Você tem lenço de papel?'),
  ('unit-1000-words-a1-04-20', 'lesson-1000-words-a1-04', 20, 'word', 'jacket', 'jaqueta', '/ˈdʒækɪt/', NULL, '[]'::jsonb, '[{"surface":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","gloss":"jaqueta"}]'::jsonb, 'Bring a jacket, it gets cold.', 'Traga uma jaqueta, esfria.')
